var ITEMS=[["WTA Tour: overview","The WTA Tour is global women's's tennis competition, founded 1973 with tour events."], ["league","WTA Tour"], ["sport","tennis"], ["region","global women's"], ["founded","1973"]];
function ask(n){var out=[],seen={};n=Math.min(n,ITEMS.length);for(var k=0;k<n;k++){var it=ITEMS[(Math.random()*ITEMS.length)|0];out.push("Q"+(k+1)+": "+it[0]+"\nA"+(k+1)+": "+it[1]);}return out.join("\n\n");}
